//! wasm4pm × unrdf Complete Lifecycle
//!
//! All types in this crate are generated by `ggen sync` from `schema/domain.ttl`.
//! The lifecycle is: Spec → Generate → Test → Deploy → Monitor → Improve → Spec.
//!
//! ## Quick Start
//!
//! ```rust
//! use wasm4pm_lifecycle::stages::LifecycleStage;
//! use wasm4pm_lifecycle::transitions::{is_valid, successors};
//! use wasm4pm_lifecycle::algorithms::algorithms_for_stage;
//!
//! // Check which stages follow Test
//! let next = successors(LifecycleStage::Test);
//! assert!(next.contains(&LifecycleStage::Deploy));
//! assert!(next.contains(&LifecycleStage::Spec)); // rework edge
//!
//! // Get wasm4pm algorithms to run at Monitor
//! let algos = algorithms_for_stage(LifecycleStage::Monitor);
//! assert!(!algos.is_empty());
//! println!("Run at Monitor: {}", algos[0].algorithm_id);
//! ```

pub mod stages;
pub mod transitions;
pub mod algorithms;

pub use stages::LifecycleStage;
pub use transitions::{StageTransition, TRANSITIONS, is_valid, successors};
pub use algorithms::{AlgorithmAssignment, ALGORITHM_ASSIGNMENTS, algorithms_for_stage, algorithm_ids_for_stage};
